def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=Counter(v for row in a for v in row).most_common(1)[0][0]
    seen=set(); bars=[]
    for r in range(h):
        for c in range(w):
            if a[r][c]==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                x,y=q.pop(); comp.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and a[nx][ny]==a[x][y]:
                        seen.add((nx,ny)); q.append((nx,ny))
            if len(comp)>=2 and any(x in (0,h-1) or y in (0,w-1) for x,y in comp):
                rs=[x for x,y in comp]; cs=[y for x,y in comp]
                if all(x==0 for x in rs): edge='top'; start=min(cs); end=max(cs)
                elif all(x==h-1 for x in rs): edge='bottom'; start=min(cs); end=max(cs)
                elif all(y==0 for y in cs): edge='left'; start=min(rs); end=max(rs)
                elif all(y==w-1 for y in cs): edge='right'; start=min(rs); end=max(rs)
                else: continue
                bars.append(dict(color=a[r][c], comp=comp, edge=edge, start=start, end=end))
    if not bars: return a
    # Each isolated colored point marks an offset within one edge bar. Copy those offsets
    # to the opposing edge bar, drawing perpendicular rays in the point's color.
    barcells={p for b in bars for p in b['comp']}
    seeds=[(r,c,a[r][c]) for r in range(h) for c in range(w)
           if a[r][c]!=bg and (r,c) not in barcells]
    patterns={}
    for b in bars:
        axis='col' if b['edge'] in ('top','bottom') else 'row'
        for r,c,color in seeds:
            pos=c if axis=='col' else r
            if b['start']<=pos<=b['end']:
                patterns.setdefault((axis,b['start'],b['end']),set()).add(pos-b['start'])
    # Process each edge bar with the offset pattern detected on its axis.
    for b in bars:
        edge=b['edge']; axis='col' if edge in ('top','bottom') else 'row'
        offsets=set()
        for (ax,s,e),offs in patterns.items():
            if ax==axis and s==b['start'] and e==b['end']:
                offsets |= offs
        for off in sorted(offsets):
            pos=b['start']+off
            if pos>b['end']: continue
            if edge=='top': r,c,dr,dc=0,pos,1,0
            elif edge=='bottom': r,c,dr,dc=h-1,pos,-1,0
            elif edge=='left': r,c,dr,dc=pos,0,0,1
            else: r,c,dr,dc=pos,w-1,0,-1
            path=[]; x,y=r+dr,c+dc
            while 0<=x<h and 0<=y<w:
                if (x,y) in barcells: break
                path.append((x,y)); x+=dr; y+=dc
            hit=next((i for i,(x,y) in enumerate(path) if a[x][y]!=bg),None)
            if hit is None:
                # Use a seed with this offset if available; otherwise use any seed color.
                color=next((col for rr,cc,col in seeds if (cc if axis=='col' else rr)==pos),seeds[0][2] if seeds else bg)
                for x,y in path:
                    if a[x][y]==bg: a[x][y]=color
